package com.ruoyi.web.controller.meeting;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.common.core.page.TableDataInfo; import com.ruoyi.system.domain.YcMeetingNotice; import com.ruoyi.system.service.IYcMeetingNoticeService;
@RestController @RequestMapping("/meeting/notice") public class YcMeetingNoticeController extends BaseController { @Autowired private IYcMeetingNoticeService service; @PreAuthorize("@ss.hasPermi('meeting:notice:list')") @GetMapping("/list") public TableDataInfo list(YcMeetingNotice query){startPage();List<YcMeetingNotice> list=service.list(query);return getDataTable(list);}@PreAuthorize("@ss.hasPermi('meeting:notice:edit')") @PostMapping public AjaxResult save(@RequestBody YcMeetingNotice notice){notice.setCreateBy(getUsername());notice.setUpdateBy(getUsername());return toAjax(service.save(notice));}}
